// <auto-generated/>
#nullable enable

using System;
using System.Globalization;
using System.Linq;
using Haitch.Roslyn.Semantics;
using Haitch.Roslyn.Types;
using Microsoft.CodeAnalysis;
using Microsoft.CodeAnalysis.CSharp;

namespace Haitch.Roslyn.Models;

internal enum ConstantValueKind
{
    Null,
    Primitive,
    String,
    Enum,
    Type,
    Array,
    Error
}

internal sealed record ConstantValue
{
    public static readonly ConstantValue Error = new(ConstantValueKind.Error, null, null, default, null);

    private ConstantValue(
        ConstantValueKind kind,
        object? value,
        TypeRef? type,
        EquatableArray<ConstantValue> elements,
        string? enumMemberName)
    {
        Kind = kind;
        Value = value;
        Type = type;
        Elements = elements;
        EnumMemberName = enumMemberName;
    }

    public ConstantValueKind Kind { get; }

    public object? Value { get; }

    public TypeRef? Type { get; }

    public EquatableArray<ConstantValue> Elements { get; }

    /// <summary>
    /// For an enum constant, the name of the single declared member with this value; <see langword="null"/>
    /// for flag combinations, undefined values and aliased values.
    /// </summary>
    public string? EnumMemberName { get; }

    public bool IsNull => Kind == ConstantValueKind.Null;

    public bool TryGetString(out string value)
    {
        if (Kind == ConstantValueKind.String && Value is string text)
        {
            value = text;
            return true;
        }

        value = "";
        return false;
    }

    public bool TryGetBoolean(out bool value)
    {
        return TryGetPrimitive(out value);
    }

    public bool TryGetInt32(out int value)
    {
        return TryGetPrimitive(out value);
    }

    public bool TryGetInt64(out long value)
    {
        return TryGetPrimitive(out value);
    }

    public bool TryGetDouble(out double value)
    {
        return TryGetPrimitive(out value);
    }

    public bool TryGetEnum<TEnum>(out TEnum value)
        where TEnum : struct, Enum
    {
        // Roslyn only reports integral underlying values, but a hand-built ForEnum can hold anything,
        // and Enum.ToObject throws on those.
        if (
            Kind == ConstantValueKind.Enum
            && Value is not null
            && System.Type.GetTypeCode(Value.GetType())
                is System.TypeCode.SByte
                    or System.TypeCode.Byte
                    or System.TypeCode.Int16
                    or System.TypeCode.UInt16
                    or System.TypeCode.Int32
                    or System.TypeCode.UInt32
                    or System.TypeCode.Int64
                    or System.TypeCode.UInt64
        )
        {
            value = (TEnum)Enum.ToObject(typeof(TEnum), Value);
            return true;
        }

        value = default;
        return false;
    }

    public bool TryGetType(out TypeRef value)
    {
        if (Kind == ConstantValueKind.Type && Type is not null)
        {
            value = Type;
            return true;
        }

        value = null!;
        return false;
    }

    public bool TryGetArray(out EquatableArray<ConstantValue> value)
    {
        value = Elements;
        return Kind == ConstantValueKind.Array;
    }

    public bool TryGetStringArray(out EquatableArray<string?> value)
    {
        value = default;

        if (Kind != ConstantValueKind.Array)
        {
            return false;
        }

        var items = new string?[Elements.Count];

        for (var i = 0; i < items.Length; i++)
        {
            ConstantValue element = Elements[i];

            if (element.Kind == ConstantValueKind.String)
            {
                items[i] = (string)element.Value!;
            }
            else if (element.Kind != ConstantValueKind.Null)
            {
                return false;
            }
        }

        value = new EquatableArray<string?>(items);
        return true;
    }

    // Exact CLR type match on purpose: a long argument must not satisfy TryGetInt32.
    private bool TryGetPrimitive<T>(out T value)
        where T : struct
    {
        if (Kind == ConstantValueKind.Primitive && Value is T typed)
        {
            value = typed;
            return true;
        }

        value = default;
        return false;
    }

    public static ConstantValue ForNull(TypeRef? type)
    {
        return new ConstantValue(ConstantValueKind.Null, null, type, default, null);
    }

    public static ConstantValue ForPrimitive(object value)
    {
        return new ConstantValue(ConstantValueKind.Primitive, value, null, default, null);
    }

    public static ConstantValue ForString(string value)
    {
        return new ConstantValue(ConstantValueKind.String, value, null, default, null);
    }

    public static ConstantValue ForEnum(TypeRef type, object underlyingValue, string? memberName = null)
    {
        return new ConstantValue(ConstantValueKind.Enum, underlyingValue, type, default, memberName);
    }

    public static ConstantValue ForType(TypeRef type)
    {
        return new ConstantValue(ConstantValueKind.Type, null, type, default, null);
    }

    public static ConstantValue ForArray(TypeRef? type, EquatableArray<ConstantValue> elements)
    {
        return new ConstantValue(ConstantValueKind.Array, null, type, elements, null);
    }

    /// <summary>
    /// Builds the model for a compile-time constant Roslyn exposes as a raw CLR value, such as an
    /// operation's <see cref="IOperation.ConstantValue"/>, a const field or a parameter's default.
    /// </summary>
    /// <param name="value">The raw constant value, <see langword="null"/> for a null constant.</param>
    /// <param name="type">The type the constant is declared or converted to.</param>
    /// <returns>The constant's model.</returns>
    public static ConstantValue From(object? value, ITypeSymbol type)
    {
        return value switch
        {
            null => ForNull(TypeRef.From(type)),
            string stringValue => ForString(stringValue),
            _ when WithoutNullable(type) is { TypeKind: TypeKind.Enum } enumType => ForEnum(TypeRef.From(enumType), value),
            _ => ForPrimitive(value),
        };
    }

    // `E? e = E.A` holds the enum's underlying value, so the enum is found inside Nullable<T>.
    private static ITypeSymbol WithoutNullable(ITypeSymbol type)
    {
        return type.NullableUnderlying() ?? type;
    }

    /// <summary>
    /// Renders the constant as the C# literal a field initializer or parameter default is written with.
    /// </summary>
    /// <returns>The literal source text.</returns>
    public string ToLiteral()
    {
        return Kind switch
        {
            ConstantValueKind.Null => "null",
            ConstantValueKind.Enum => RenderEnum(),
            ConstantValueKind.String => SymbolDisplay.FormatLiteral((string)Value!, quote: true),
            ConstantValueKind.Primitive => RenderPrimitive(Value!),
            _ => throw new InvalidOperationException($"A constant value of kind {Kind} has no literal."),
        };
    }

    // A negative underlying value renders as "(global::E)-1", which the compiler parses as a
    // subtraction (the cast-ambiguity rule does not treat '-' as an unambiguous follow token), so
    // the literal is parenthesized to force the cast: "(global::E)(-1)".
    private string RenderEnum()
    {
        var literal = RenderPrimitive(Value!);

        if (literal.StartsWith("-", StringComparison.Ordinal))
        {
            literal = $"({literal})";
        }

        return $"({Type!.FullyQualifiedName}){literal}";
    }

    // Every number is formatted with the invariant culture, so generated source does not depend on
    // the build machine's decimal separator.
    private static string RenderPrimitive(object value)
    {
        return value switch
        {
            bool boolValue => boolValue ? "true" : "false",
            char charValue => SymbolDisplay.FormatLiteral(charValue, quote: true),
            float floatValue => RenderFloat(floatValue),
            double doubleValue => RenderDouble(doubleValue),
            decimal decimalValue => decimalValue.ToString(CultureInfo.InvariantCulture) + "m",
            long longValue => longValue.ToString(CultureInfo.InvariantCulture) + "L",
            ulong ulongValue => ulongValue.ToString(CultureInfo.InvariantCulture) + "UL",
            uint uintValue => uintValue.ToString(CultureInfo.InvariantCulture) + "U",
            int or short or ushort or byte or sbyte =>
                Convert.ToInt64(value, CultureInfo.InvariantCulture).ToString(CultureInfo.InvariantCulture),
            _ => throw new ArgumentOutOfRangeException(nameof(value), value, "Unsupported primitive constant value."),
        };
    }

    // NaN and the infinities have no literal token in C#; the well-known static fields are the
    // only way to express them in source. Finite values round-trip through "G9" (float) / "G17"
    // (double), the exact-round-trip precision for each type.
    private static string RenderFloat(float value)
    {
        if (float.IsNaN(value))
        {
            return "float.NaN";
        }

        if (float.IsPositiveInfinity(value))
        {
            return "float.PositiveInfinity";
        }

        if (float.IsNegativeInfinity(value))
        {
            return "float.NegativeInfinity";
        }

        return value.ToString("G9", CultureInfo.InvariantCulture) + "f";
    }

    private static string RenderDouble(double value)
    {
        if (double.IsNaN(value))
        {
            return "double.NaN";
        }

        if (double.IsPositiveInfinity(value))
        {
            return "double.PositiveInfinity";
        }

        if (double.IsNegativeInfinity(value))
        {
            return "double.NegativeInfinity";
        }

        return value.ToString("G17", CultureInfo.InvariantCulture) + "d";
    }

    public static ConstantValue From(TypedConstant constant)
    {
        // A bad argument expression (e.g. a typo) yields Kind.Error; constant.Value and
        // constant.IsNull are not safe to read for it, so it is handled before anything else.
        if (constant.Kind == TypedConstantKind.Error)
        {
            return Error;
        }

        TypeRef? type = constant.Type is null ? null : TypeRef.From(constant.Type);

        if (constant.IsNull)
        {
            return ForNull(type);
        }

        return constant.Kind switch
        {
            TypedConstantKind.Primitive when constant.Value is string stringValue => ForString(stringValue),
            TypedConstantKind.Primitive => ForPrimitive(constant.Value!),
            TypedConstantKind.Enum => ForEnum(type!, constant.Value!, FindEnumMemberName(constant)),
            TypedConstantKind.Type => ForType(TypeRef.From((ITypeSymbol)constant.Value!)),
            TypedConstantKind.Array => ForArray(type, constant.Values.Select(From).ToEquatableArray()),
            _ => throw new ArgumentOutOfRangeException(nameof(constant), constant.Kind, "Unsupported typed constant kind."),
        };
    }

    private static string? FindEnumMemberName(TypedConstant constant)
    {
        if (constant.Type is not INamedTypeSymbol enumType)
        {
            return null;
        }

        string? name = null;

        foreach (IFieldSymbol field in enumType.EnumMembers())
        {
            if (!Equals(field.ConstantValue, constant.Value))
            {
                continue;
            }

            if (name is not null)
            {
                return null;
            }

            name = field.Name;
        }

        return name;
    }
}
